-- Solo lectura. ANTES: 1 «PUBLICADA», 2 «PUBLICADA», 3 «PUBLICADA». DESPUÉS: 1 «CON ESTE CAMBIO» (anótela), 2 igual, 3 «CON ESTE CAMBIO».
select o, k, v, estado from (
  select 1 as o, '1 funciones de campo (conjunto, todas)' as k, (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p where p.pronamespace = 'campo'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_campo\_%')) as v,
         case (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p where p.pronamespace = 'campo'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_campo\_%')) when '261bed3c9242f6261f845ec4e1374b3a' then 'PUBLICADA (22-nov): lista para este cambio' when 'b4e8896671c9acb981b42a8072aa52cf' then 'CON ESTE CAMBIO' else 'OTRA: deténgase y avise' end as estado
  union all
  select 2, '2 funciones del acta (conjunto)', (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p where p.pronamespace = 'acta'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_acta\_%')), case (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p where p.pronamespace = 'acta'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_acta\_%')) when '111506c690249ad3b56ebf572566434c' then 'PUBLICADA (no cambia con este paquete)' else 'OTRA: deténgase y avise' end
  union all
  select 3, '3 public.geoportal_campo_preparar_subida(text,integer,text,text,text)', md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_preparar_subida(text,integer,text,text,text)'))),
         case md5(pg_get_functiondef(to_regprocedure('public.geoportal_campo_preparar_subida(text,integer,text,text,text)'))) when '6a2ef927316ed4aa2936eadfb9b0a0cd' then 'PUBLICADA' when 'a00d66705d7a0c88a38ab5d882153669' then 'CON ESTE CAMBIO' else 'OTRA: deténgase y avise' end
) t order by o;
